    try { cons = Z.simulate(sc, spec.t0, { samples: 1400 }); }
    catch (e) { cons = null; }
    if (!cons || !cons.result || !cons.result.frames.length) return null;

    var AU = 1.495978707e8;                       /* km */
    var fr = cons.result.frames, x = [], y = [], ts = [], sx = [], sy = [];
